INSERT INTO public.adoption_applications (id, created_at, decided_at, pet_care_plan, reason_for_adoption, shelter_notes, status, submitted_at, updated_at, veterinary_care_plan_notes, adopter_id, adopter_profile_id, animal_id) VALUES (2, '2026-09-11 12:03:58.223281', '2026-10-16 12:30:06.567703', 'Sunny apartment with custom cat wall shelves, window beds, and premium wet/dry nutrition.', 'I work from home and want to provide a quiet, affectionate forever sanctuary for an indoor cat.', 'Adoption finalized and certificate handed over. Follow-up photo updates show Cleo thriving!', 'COMPLETED', '2026-10-05 12:30:06.567703', NULL, 'Regular bi-annual check-ups and immediate emergency veterinary coverage', 72, 2, 10);
INSERT INTO public.adoption_applications (id, created_at, decided_at, pet_care_plan, reason_for_adoption, shelter_notes, status, submitted_at, updated_at, veterinary_care_plan_notes, adopter_id, adopter_profile_id, animal_id) VALUES (3, '2026-09-11 12:03:58.23673', NULL, 'Active lifestyle with daily running routine. Roommates are all enthusiastic dog lovers.', 'I love indies and want an energetic companion for trail running and outdoor adventures.', 'Preliminary interview passed. Virtual house safety check scheduled with applicant.', 'HOUSE_CHECK_PENDING', '2026-10-05 12:30:06.586872', NULL, 'Regular bi-annual check-ups and immediate emergency veterinary coverage', 73, 3, 9);
INSERT INTO public.adoption_applications (id, created_at, decided_at, pet_care_plan, reason_for_adoption, shelter_notes, status, submitted_at, updated_at, veterinary_care_plan_notes, adopter_id, adopter_profile_id, animal_id) VALUES (4, '2026-09-11 12:03:58.251041', NULL, 'Private fenced lawn, family members home throughout the day, regular weekend outings.', 'Our family has deeply missed having a gentle dog in our home. We want to welcome Penny as our daughter''s best friend.', 'Application reviewed by shelter manager. Verified spacious accommodation and solid prior pet history.', 'UNDER_REVIEW', '2026-10-05 12:30:06.606302', NULL, 'Regular bi-annual check-ups and immediate emergency veterinary coverage', 74, 4, 14);
INSERT INTO public.adoption_applications (id, created_at, decided_at, pet_care_plan, reason_for_adoption, shelter_notes, status, submitted_at, updated_at, veterinary_care_plan_notes, adopter_id, adopter_profile_id, animal_id) VALUES (5, '2026-09-11 12:03:58.262812', NULL, 'Large open-air farm estate, fresh balanced meals, daily runs, and 24-hr farm veterinary visits.', 'Max will have 5 acres of open secure grounds to run, play, and live a joyful life on our family farm.', 'New submission received. Awaiting initial questionnaire review.', 'SUBMITTED', '2026-10-05 12:30:06.624887', NULL, 'Regular bi-annual check-ups and immediate emergency veterinary coverage', 75, 5, 13);
INSERT INTO public.adoption_applications (id, created_at, decided_at, pet_care_plan, reason_for_adoption, shelter_notes, status, submitted_at, updated_at, veterinary_care_plan_notes, adopter_id, adopter_profile_id, animal_id) VALUES (6, '2026-09-11 12:03:58.274113', '2026-10-16 12:30:06.656694', 'Gradual scent-swapping introduction in a dedicated nursery room, high-protein grain-free diet.', 'Looking for a playful companion for our resident cat and a sweet ginger boy to cherish.', 'Application approved! Adopter has extensive feline experience and secure balcony netting.', 'APPROVED', '2026-10-05 12:30:06.656694', NULL, 'Regular bi-annual check-ups and immediate emergency veterinary coverage', 76, 6, 15);
