INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (6, 40, '2026-09-10 10:46:31.100979', 'Buddy was rescued from an industrial park and has grown into the gentlest companion. He is fully house-trained, knows basic obedience, and loves curling up by your feet.', 'Gentle, loyal, and loves outdoor fetch', '2026-09-01 10:46:31.100979', NULL, 'Needs 45 minutes of daily exercise. Good with first-time dog owners.', 'APPROVED', '2026-08-31 10:46:31.100979', NULL, 8, NULL, 'LARGE');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (7, 25, '2026-09-10 10:46:31.142895', 'Shadow is an exceptionally smart 8-month-old indie puppy. He learns commands in minutes and is looking for an active family ready for fun hikes.', 'Energetic, intelligent, and highly affectionate', '2026-09-01 10:46:31.142895', NULL, 'Fenced yard preferred. Very playful with other dogs.', 'APPROVED', '2026-08-31 10:46:31.142895', NULL, 9, NULL, 'MEDIUM');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (8, 30, '2026-09-10 10:46:31.186976', 'Cleo is a serene 1-year-old Calico queen. She will greet you with sweet purrs and happily nap next to your desk while you work.', 'Calm, gentle, and adores cuddles', '2026-09-01 10:46:31.186976', NULL, 'Indoor-only home preferred. Quiet environment.', 'APPROVED', '2026-08-31 10:46:31.186976', NULL, 10, NULL, 'SMALL');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (9, 45, '2026-09-10 10:46:31.278242', 'Max is a muscular and loving Boxer mix who loves human companionship. He walks beautifully on leash and knows sit, stay, and paw.', 'Playful, protective, and full of life', '2026-09-01 10:46:31.278242', NULL, 'Experienced dog owner preferred. Great jogging companion.', 'APPROVED', '2026-08-31 10:46:31.278242', NULL, 13, NULL, 'LARGE');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (10, 50, '2026-09-10 10:46:31.305841', 'Penny radiates happiness wherever she goes. She is eager to learn, adores belly rubs, and is ready to be your family''s best friend.', 'Warm-hearted, joyful, and affectionate', '2026-09-01 10:46:31.305841', NULL, 'Wonderful family dog. Good with young kids.', 'APPROVED', '2026-08-31 10:46:31.305841', NULL, 14, NULL, 'MEDIUM');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (11, 30, '2026-09-11 12:03:56.852463', 'Oliver is a bright 1-year-old ginger boy who chirps happily when you walk in the room. He is great with other cats.', 'Playful, chatty, and curious explorer', '2026-09-02 12:03:56.852463', NULL, 'Indoor home with scratching tree preferred.', 'APPROVED', '2026-09-01 12:03:56.852463', NULL, 15, NULL, 'SMALL');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (12, 35, '2026-09-11 12:03:56.876561', 'Bruno is a loving 20-month-old hound mix who will steal your heart with his big expressive eyes and joyful tail wags.', 'Inquisitive, social, and gentle hound mix', '2026-09-02 12:03:56.876561', NULL, 'Needs daily neighborhood sniff-walks.', 'APPROVED', '2026-09-01 12:03:56.876561', NULL, 16, NULL, 'MEDIUM');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (13, 25, '2026-09-11 12:03:56.895254', 'Mittens is dressed for a black-tie gala every single day. She loves sunbeams and curling up quietly beside you while reading.', 'Graceful, quiet, and devoted cuddlebug', '2026-09-02 12:03:56.895254', NULL, 'Cozy apartment or quiet household.', 'APPROVED', '2026-09-01 12:03:56.895254', NULL, 17, NULL, 'SMALL');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (14, 45, '2026-09-11 12:03:56.918168', 'Rocky is a noble German Shepherd cross who thrives with agility games, frisbee fetch, and dedicated obedience companionship.', 'Intelligent, loyal protector and athletic partner', '2026-09-02 12:03:56.918168', NULL, 'Active owners with yard preferred.', 'APPROVED', '2026-09-01 12:03:56.918168', NULL, 18, NULL, 'LARGE');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (15, 35, '2026-09-11 12:03:56.940888', 'Bella has the gentlest heart and silky caramel fur. She gets along with all dogs and loves nothing more than giving joyful kisses.', 'Sweet, cheerful, and loves cuddling', '2026-09-02 12:03:56.940888', NULL, 'Regular grooming recommended.', 'APPROVED', '2026-09-01 12:03:56.940888', NULL, 19, NULL, 'MEDIUM');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (16, 30, '2026-09-11 12:03:56.958488', 'Simba looks like a miniature lion with a heart of pure gold. He will supervise your household with serene, loving grace.', 'Regal, fluffy, and serene gentleman', '2026-09-02 12:03:56.958488', NULL, 'Daily coat brushing required.', 'APPROVED', '2026-09-01 12:03:56.958488', NULL, 20, NULL, 'SMALL');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (17, 35, '2026-09-11 12:03:56.973226', 'Milo may be small in stature, but he has an enormous personality. He loves burrowing under soft blankets and going on lively park walks.', 'Spunky, loving, and full of personality', '2026-09-02 12:03:56.973226', NULL, 'Avoid jumping from high furniture to protect back.', 'APPROVED', '2026-09-01 12:03:56.973226', NULL, 21, NULL, 'SMALL');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (18, 25, '2026-09-11 12:03:56.987746', 'Luna was rescued as a fragile puppy and has blossomed into a graceful, loyal companion ready to shower her new family with affection.', 'Joyful, agile, and wonderfully loyal', '2026-09-02 12:03:56.987746', NULL, 'Enjoys interactive puzzle toys.', 'APPROVED', '2026-09-01 12:03:56.987746', NULL, 22, NULL, 'MEDIUM');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (19, 40, '2026-09-11 12:03:57.008265', 'Cooper is a quintessential gentle giant who loves tennis balls, splashing in water puddles, and snuggling his head against your shoulder.', 'Affectionate, goofy, and loves water', '2026-09-02 12:03:57.008265', NULL, 'Great family companion for homes with children.', 'APPROVED', '2026-09-01 12:03:57.008265', NULL, 23, NULL, 'LARGE');
INSERT INTO public.adoption_listings (id, adoption_fee, created_at, listing_description, personality, reviewed_at, reviewer_notes, special_care_requirements, status, submitted_at, updated_at, animal_id, reviewed_by, size) VALUES (20, 35, '2026-09-11 12:03:57.024318', 'Daisy is a sweet curly-coated angel who walks like a ballerina and loves nap time. She is low-shedding and wonderfully polite indoors.', 'Gentle, low-shedding, and polite angel', '2026-09-02 12:03:57.024318', NULL, 'Ideal for apartment living.', 'APPROVED', '2026-09-01 12:03:57.024318', NULL, 24, NULL, 'SMALL');
