INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (1, 1, 0, 'Core Canine Vaccination Guidelines', 'Core vaccination protects canines from severe, potentially fatal systemic diseases globally.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (2, 1, 1, 'Puppy Core Administration Schedule', 'Puppies should receive their initial core vaccine at 6 to 8 weeks of age, followed by boosters every 2 to 4 weeks until 16 weeks of age or older.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (3, 1, 2, 'Non-Core Canine Vaccines', 'Non-core vaccines are selected based on lifestyle, geographic risk, and exposure:
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (4, 1, 3, 'Core Feline Vaccination Guidelines', 'The core vaccines for domestic cats are:
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (5, 2, 0, 'Emergency Dietary Toxicities in Pets', 'The following common household foods and substances are strictly toxic to canines and felines:
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (6, 2, 1, 'Species-Appropriate Balanced Diets', '- Cats are obligate carnivores requiring essential animal-derived amino acids, particularly Taurine, Arginine, and preformed Vitamin A. Taurine deficiency causes dilated cardiomyopathy (DCM) and central retinal degeneration.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (7, 3, 0, 'Periodontal Hygiene and Dental Prevention', 'Over 80% of dogs and 70% of cats exhibit clinical signs of periodontal disease by 3 years of age.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (8, 3, 1, 'Ear Canal Hygiene and Otitis Prevention', 'Perform weekly otic examinations for erythema, ceruminous discharge, or foul odor.
