INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (11, 5, 0, 'Pediatric and Young Animal Deworming Protocols', 'Intestinal parasites are extremely common in young puppies and kittens due to maternal transmission (transmammary roundworms and hookworms through nursing in kittens and puppies, plus transplacental transmission in puppies) and early environmental contamination.', '{0,0,0,-0.03474915,0,0,0,-0.052123725,0.059073556,0,0,0,-0.05038627,-0.038224064,0.08339796,0,-0.052123725,0,0.10077254,0,0,0,0.02084949,0.088610336,0,0,-0.07644813,0,0,-0.029536778,-0.059073556,0,0,0.02084949,-0.14420897,0,0.022586945,0,-0.008687288,0,-0.033011694,-0.031274233,0,0.033011694,0.039961524,-0.11119727,-0.033011694,0.033011694,0,0,0,0,0,0,0,-0.026061863,0,0.02084949,0.031274233,0.15115881,-0.029536778,0,0.05038627,0,0,0,0,0,0.11293474,0,0,-0.06776084,0.057336096,0,0,0,-0.059073556,0,-0.022586945,0,0,0,0.029536778,0,0,0,0.07123576,-0.012162203,0.039961524,0,0,-0.15637118,0,-0.022586945,0,0,0,0,-0.033011694,-0.04169898,0,0,0.026061863,0.05038627,0.038224064,-0.024324404,0,0,0,0,0,0.03474915,0,0.059073556,-0.039961524,0,0,0.0017374558,0,-0.02084949,0.12335949,0,0.033011694,0,-0.038224064,0,0.14073405,0.026061863,0.05559864,0,0,0,0.033011694,0,0,0.06254847,0,-0.008687288,-0.022586945,0,0,-0.0034749159,0,-0.02084949,0,-0.02779932,0,0,0,0,-0.04169898,0.0069498317,-0.052123725,0,0,0,-0.088610336,0.029536778,-0.074710675,0,0,0,0,-0.033011694,0.11293474,0.03474915,0.033011694,0,0,-0.02779932,0,0,0,-0.005212376,0,0.088610336,0,0,0.07644813,0,0,-0.022586945,0,0,0.048648812,0.022586945,-0.14073405,0,-0.09208525,0,0,-0.033011694,0.07992303,-0.02779932,0.04169898,0.02779932,0.088610336,0,0,0,0.031274233,-0.038224064,0,-0.039961524,0.04169898,-0.033011694,0.029536778,0,0,-0.039961524,0,0,0,0,0.033011694,-0.033011694,0.02258695,0.019112034,-0.033011694,0.024324404,0,0,0,0.06776084,0,0,0,0.121622026,-0.07644813,-