INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (12, 5, 1, 'Core Kitten Deworming Schedule', 'Kittens should begin preventive anthelmintic treatment at 2 to 3 weeks of age.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (13, 5, 2, 'Core Puppy Deworming Schedule', 'Puppies should begin preventive deworming at 2 weeks of age.
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (14, 5, 3, 'Common Intestinal Parasites', '1. Roundworms (Toxocara cati in cats, Toxocara canis in dogs): Cause pot-bellied appearance, unthriftiness, vomiting, diarrhea, and poor weight gain. Zoonotic potential (visceral and ocular larva migrans in humans).
INSERT INTO public.knowledge_chunks (id, document_id, chunk_index, section_title, content, embedding, embedding_model, created_at) VALUES (15, 5, 4, 'Anthelmintic Medications and Critical Safety Boundaries', '- Pediatric Veterinary Formulations: Pyrantel pamoate is the clinical gold standard for young puppies and kittens against roundworms and hookworms. Fenbendazole offers broader coverage (roundworms, hookworms, whipworms, and Giardia). Praziquantel is indicated for cestodes (tapeworms).
INSERT INTO public.medical_records (id, created_at, deworming_info, diagnosis, examination_date, follow_up_date, follow_up_notes, follow_up_required, health_status, lab_investigations, medication, parasite_control_info, sterilization_status, treatment, veterinary_notes, weight_kg, animal_id, veterinarian_id) VALUES (6, '2026-09-10 10:46:31.074362', NULL, 'Annual Preventive Examination', '2026-09-05', NULL, NULL, false, 'Fit for Adoption', NULL, NULL, NULL, NULL, 'Administered multivitamin paste and broad-spectrum dewormer.', 'Fully healthy adult dog. Clear lungs, sound heart sounds, clean ears.', 26.5, 8, 2);
